function countPalindromes(str) {
  let count = 0;
  for (let i = 0; i < str.length; i++) {
    for (let j = i; j < str.length; j++) {
      const sub = str.slice(i, j + 1);
      if (sub === sub.split('').reverse().join('')) count++;
    }
  }
  return count;
}
console.log(countPalindromes('aaa'));
